// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 seed) public {
        // Caller is a contract that cannot receive ETH; it has zero credit in c.
        NonPayable actor = new NonPayable();
        vm.assume(seed >= 0);

        // Drive c through withdrawAll from the zero-credit actor.
        vm.prank(address(actor));
        try c.withdrawAll() {
            // Reference: with credit == 0, no call is made, so this succeeds.
            assertTrue(true);
        } catch {
            // Rule: withdrawAll never reverts for a caller with zero credit.
            assertTrue(false, "withdrawAll reverted for zero-credit caller");
        }
    }
}

contract NonPayable {
    // No receive/fallback: any ETH transfer (even 0 value call) to it reverts.
    function callTarget(ReentrancyDAO target) external {
        target.withdrawAll();
    }
}
